```bash
cat <<'EOF' > test_child_stats.go
package main

import (
	"fmt"
	"reflect"
)

// Simplified version of CollectionStats
type CollectionStats struct {
	TotGet uint64
	TotSet uint64
}

// Simplified version of collection
type collection struct {
	stats *CollectionStats
	name  string
}

func main() {
	// Parent collection with its own stats
	parentStats := &CollectionStats{}
	parent := &collection{
		stats: parentStats,
		name:  "parent",
	}

	// Before fix: Child collections would share the same stats instance
	fmt.Println("Before fix:")
	child1 := &collection{
		stats: parentStats, // Sharing parent's stats
		name:  "child1",
	}

	child2 := &collection{
		stats: parentStats, // Sharing parent's stats
		name:  "child2",
	}

	// Check if they share the same stats instance
	fmt.Printf("Parent and child1 share stats: %t\n", parent.stats == child1.stats)
	fmt.Printf("Child1 and child2 share stats: %t\n", child1.stats == child2.stats)

	// After fix: Each child collection gets its own stats instance
	fmt.Println("\nAfter fix:")
	child3 := &collection{
		stats: &CollectionStats{}, // New instance
		name:  "child3",
	}

	child4 := &collection{
		stats: &CollectionStats{}, // New instance
		name:  "child4",
	}

	// Check if they have separate stats instances
	fmt.Printf("Parent and child3 share stats: %t\n", parent.stats == child3.stats)
	fmt.Printf("Child3 and child4 share stats: %t\n", child3.stats == child4.stats)
	fmt.Printf("Child3 and child4 have same struct type: %t\n", reflect.TypeOf(child3.stats) == reflect.TypeOf(child4.stats))
}
EOF
